/**
 * Base64-embedded logo for the public Swagger doc's topbar branding, matching
 * the frontend's own logo (frontend/public/logo-clean.png). Embedded as a
 * source string rather than read from disk at boot: the API and frontend
 * ship as separate Docker images (see Dockerfile / frontend/Dockerfile), so
 * the frontend's public/ directory is not guaranteed to exist on the API's
 * filesystem at runtime — a file read here would be a new deploy-time
 * failure mode. A string constant has no such dependency.
 */
export const SWAGGER_LOGO_BASE64_PNG = '';
